examples.top:
TypedHtml.div [ Native.attribute "id" "scrollContainer" ]
    [ M3e.appBar [ M3e.AppBar.for "scrollContainer" ]
        [ M3e.AppBar.leading (M3e.iconButton [ TypedHtml.Aria.label "Back" ] [ M3e.icon [ M3e.Icon.name "arrow_back" ] [] ])
        , M3e.AppBar.title (Kit.text "Top 10 hiking trails")
        , M3e.AppBar.subtitle (Kit.text "Discover popular trails")
        , M3e.AppBar.trailing
            (M3e.iconButton
                [ TypedHtml.Aria.label "Bookmark"
                , M3e.IconButton.variant M3e.Values.tonal
                ]
                [ M3e.icon
                    [ M3e.Icon.name "bookmark"
                    , M3e.Icon.filled True
                    ]
                    []
                ]
            )
        ]
    , TypedHtml.div [ Native.attribute "class" "scroll-item" ] [ Kit.text "Scroll down to see the elevation effect" ]
    ]

examples.build:
[ M3e.FormField.build
    |> M3e.FormField.withLabel (TypedHtml.label [ Native.attribute "for" "fruit4" ] [ Kit.text "Choose your favorite fruit" ])
    |> M3e.FormField.withChild (TypedHtml.input [ Native.attribute "id" "fruit4" ] [])
    |> M3e.FormField.toElement
, M3e.Autocomplete.view
    [ M3e.Attributes.class "custom-filter"
    , M3e.Autocomplete.for "fruit4"
    ]
    [ M3e.Option.build { content = Kit.text "Apples" }
        |> M3e.Option.toElement
    , M3e.Option.build { content = Kit.text "Oranges" }
        |> M3e.Option.toElement
    , M3e.Option.build { content = Kit.text "Bananas" }
        |> M3e.Option.toElement
    , M3e.Option.build { content = Kit.text "Grapes" }
        |> M3e.Option.toElement
    ]
]

